{
  "incident_id": "exfiltration-001",
  "telemetry_version": 1,
  "assessment": "Confirmed active exfiltration from critical host web-01 to c2-01 and confirmed lateral movement attempts from web-01. Immediate containment of exfiltration and lateral spread is required. Full isolation of web-01 is prohibited by policy; therefore, targeted egress blocking and lateral restriction are the minimal sufficient controls.",
  "evidence_review": [
    {
      "evidence_id": "E1",
      "decision": "contain",
      "reason": "Confirmed active unauthorized data transfer from web-01 to c2-01. Blocking egress to c2-01 from web-01 directly interrupts the observed exfiltration path while preserving management and evidence collection channels."
    },
    {
      "evidence_id": "E2",
      "decision": "contain",
      "reason": "Confirmed unauthorized lateral access attempt originating on web-01. Restricting lateral traffic on web-01 prevents further lateral movement to other assets."
    }
  ],
  "actions": [
    {
      "kind": "block_egress",
      "target_id": "c2-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "E1"
      ],
      "reason": "Interrupts confirmed active exfiltration from web-01 to c2-01. This targeted egress block minimizes availability impact on web-01 compared to full isolation, while preserving required management and evidence_collector channels.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    },
    {
      "kind": "restrict_lateral",
      "target_id": "web-01",
      "scope_host_ids": [],
      "evidence_ids": [
        "E2"
      ],
      "reason": "Prevents confirmed lateral movement attempts originating from web-01. This restricts the attacker's ability to spread to other hosts without disrupting web-01's primary services or required channels.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact on web-01's legitimate business functions is unknown as specific dependency mappings are not provided, though targeted controls are preferred to minimize disruption."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

